        grid-template-columns: 1fr;
      }

      .staff-container {
        grid-template-columns: 1fr;
      }
    }

    @media screen and (max-width: 768px) {
      :root {
        --section-padding: 15px;
        --font-size: 14px;
      }

      .game-container {
        margin: 5px;
        padding: 10px;
        border-width: 2px;
      }

      .navigation-section {
        grid-template-columns: repeat(2, 1fr);
        padding: 10px;
      }

      .nav-item {
        padding: 10px;
      }

      .nav-item i {
        font-size: 1.2em;
        margin-bottom: 5px;
      }

      .section-header {
        font-size: 1.5em;
      }

      .section-header:before,
      .section-header:after {
        width: 20%;
      }

      .time-location-info {
        flex-direction: column;
        gap: 10px;
      }

      .dish-grid {
        grid-template-columns: 1fr;
      }

      .taste-preferences {
        flex-direction: column;
        gap: 10px;
      }

      .customer-header {
        flex-direction: column;
        gap: 5px;
      }

      .review-card {
        padding: 15px;
      }

      .staff-card {
        margin: 10px 0;
      }

      .task-header {
        font-size: 1.1em;
      }
    }

    @media screen and (max-width: 480px) {
      :root {
        --font-size: 12px;
      }

      .game-container {
        margin: 0;
        border-width: 0;
      }

      .navigation-section {
        gap: 5px;
        padding: 5px;
      }

      .nav-item {
        padding: 8px;
      }

      .section-header:before,
      .section-header:after {
        display: none;
      }

      .overview-card,
      .kitchen-card,
      .staff-card,
      .task-section {
        padding: 10px;
      }

      .dish-card {
        margin: 5px 0;
      }

      .requirement-tags {
        flex-wrap: wrap;
      }

      .requirement-tag {
        margin: 2px;
      }

      .save-status {
        left: 50%;
        transform: translateX(-50%);
        right: auto;
        bottom: 10px;
      }
    }

    /* 添加触摸设备支持 */
    @media (hover: none) {
      .nav-item:hover {
        background-color: inherit;
        color: inherit;
      }

      .nav-item:active {
        background-color: var(--primary-color);
        color: white;
      }

      .ingredient-item {
        touch-action: none;
      }

      .create-dish-button:active {
        transform: scale(0.98);
      }
    }

    /* 添加深色模式支持 */
    @media (prefers-color-scheme: dark) {
      :root {
        --primary-color: #8E44AD;
        --border-color: #8E44AD;
        --background-color: #2d2d2d;
        --text-color: #f5efe6;
      }

      body {
        background-color: #2d2d2d;
      }

      .overview-card,
      .kitchen-card,
      .staff-card,
      .task-section,
      .review-card {
        background: #3d3d3d;
      }

      .review-text,
      .dish-description {
        background: #4d4d4d;
        color: #f5efe6;
      }

      .taste-tag,
      .requirement-tag,
      .completed-tag {
        background: #4d4d4d;
        color: #f5efe6;
      }

      .task-status {
        background: #3d4d3e;
        color: #4CAF50;
      }
    }
  </style>
</head>

<body>
  <div class="game-container">
    <div class="navigation-section">
      <div class="nav-item active" data-section="main">
        <i class="fas fa-home"></i>
        <span>正文</span>
      </div>
      <div class="nav-item" data-section="overview">
        <i class="fas fa-chart-line"></i>
        <span>营业总览</span>
      </div>
      <div class="nav-item" data-section="dining">
        <i class="fas fa-utensils"></i>
        <span>食堂区域</span>
      </div>
      <div class="nav-item" data-section="kitchen">
        <i class="fas fa-fire"></i>
        <span>厨房</span>
      </div>
      <div class="nav-item" data-section="staff">
        <i class="fas fa-users"></i>
        <span>员工信息</span>
      </div>
      <div class="nav-item" data-section="tasks">
        <i class="fas fa-tasks"></i>
        <span>任务</span>
      </div>
      <div class="nav-item" data-section="menu">
        <i class="fas fa-book-open"></i>
        <span>菜单</span>
      </div>
      <div class="nav-item" data-section="settings">
        <i class="fas fa-cog"></i>
        <span>设置</span>
      </div>
    </div>

    <div id="main" class="content-section active">
      <!-- 内容将由JavaScript动态生成 -->
    </div>
    <div id="overview" class="content-section">
      <!-- 内容将由JavaScript动态生成 -->
    </div>
    <div id="dining" class="content-section">
      <!-- 内容将由JavaScript动态生成 -->
    </div>
    <div id="kitchen" class="content-section">
      <!-- 内容将由JavaScript动态生成 -->
    </div>
    <div id="staff" class="content-section">
      <!-- 内容将由JavaScript动态生成 -->
    </div>
    <div id="tasks" class="content-section">
      <!-- 内容将由JavaScript动态生成 -->
    </div>
    <div id="menu" class="content-section">
      <!-- 内容将由JavaScript动态生成 -->
    </div>
    <div id="settings" class="content-section">
      <h2 class="section-header">系统设置</h2>
      <div class="settings-container">
        <!-- 字体设置 -->
        <div class="settings-card">
          <div class="settings-header">
            <i class="fas fa-font"></i>
            字体设置
          </div>
          <div class="settings-content">
            <div class="settings-group">
              <div class="settings-label">选择字体样式</div>
              <div class="font-options">
                <div class="font-option active" data-font="WenQuanYi">
                  <input type="radio" name="font" checked>
                  <div class="font-preview" style="font-family: 'WenQuanYi Bitmap Song 13px'">
                    文泉驿点阵宋体 - 餐厅经营模拟游戏
                  </div>
                </div>
                <div class="font-option" data-font="Kingnam">
                  <input type="radio" name="font">
                  <div class="font-preview" style="font-family: 'Kingnam Maiyuan'">
                    金南麦圆体 - 餐厅经营模拟游戏
                  </div>
                </div>
              </div>
            </div>
            <div class="settings-group">
              <div class="settings-label">字体大小</div>
              <input type="range" min="10" max="34" value="16" class="font-size-slider" id="fontSizeSlider">
              <span class="font-size-value">16px</span>
            </div>
          </div>
        </div>

        <!-- 主题设置 -->
        <div class="settings-card">
          <div class="settings-header">
            <i class="fas fa-palette"></i>
            主题设置
          </div>
          <div class="settings-content">
            <div class="settings-group">
              <div class="settings-label">选择颜色主题</div>
              <div class="color-options">
                <div class="color-option active" style="background: #453B34" data-theme="default">
                  默认主题
                </div>
                <div class="color-option" style="background: #2C3E50" data-theme="dark">
                  深色主题
                </div>
                <div class="color-option" style="background: #8E44AD" data-theme="purple">
                  紫色主题
                </div>
                <div class="color-option" style="background: #16A085" data-theme="green">
                  绿色主题
                </div>
              </div>
            </div>
          </div>
        </div>

        <!-- 窗口设置 -->
        <div class="settings-card">
          <div class="settings-header">
            <i class="fas fa-window-maximize"></i>
            窗口设置
          </div>
          <div class="settings-content">
            <div class="settings-group">
              <div class="settings-label">窗口大小</div>
              <div class="window-size">
                <input type="number" class="size-input" id="windowWidth" value="1200" min="800" max="1920">
                <span class="size-separator">×</span>
                <input type="number" class="size-input" id="windowHeight" value="800" min="600" max="1080">
              </div>
            </div>
          </div>
        </div>
      </div>

      <div class="save-status">
        <i class="fas fa-check-circle"></i>
        设置已自动保存
      </div>
    </div>
  </div>

  <script>
    document.addEventListener('DOMContentLoaded', function () {
      const navItems = document.querySelectorAll('.nav-item');
      const contentSections = document.querySelectorAll('.content-section');

      navItems.forEach(item => {
        item.addEventListener('click', function () {
          navItems.forEach(nav => nav.classList.remove('active'));
          this.classList.add('active');

          const sectionId = this.getAttribute('data-section');
          contentSections.forEach(section => section.classList.remove('active'));
          document.getElementById(sectionId).classList.add('active');
        });
      });
    });

    // 设置相关的JavaScript代码
    document.addEventListener('DOMContentLoaded', function () {
      // 加载保存的设置
      loadSettings();

      // 字体选择
      const fontOptions = document.querySelectorAll('.font-option');
      fontOptions.forEach(option => {
        option.addEventListener('click', function () {
          fontOptions.forEach(opt => opt.classList.remove('active'));
          this.classList.add('active');
          const font = this.dataset.font;
          const root = document.documentElement;
          if (font === 'WenQuanYi') {
            root.style.setProperty('--font-family', '"WenQuanYi Bitmap Song 13px"');
          } else {
            root.style.setProperty('--font-family', '"Kingnam Maiyuan"');
          }
          saveSettings();
        });
      });

      // 字体大小调节
      const fontSizeSlider = document.getElementById('fontSizeSlider');
      const fontSizeValue = document.querySelector('.font-size-value');
      fontSizeSlider.addEventListener('input', function () {
        const size = this.value;
        fontSizeValue.textContent = size + 'px';
        document.documentElement.style.setProperty('--font-size', size + 'px');
        saveSettings();
      });

      // 颜色主题
      const colorOptions = document.querySelectorAll('.color-option');
      colorOptions.forEach(option => {
        option.addEventListener('click', function () {
          colorOptions.forEach(opt => opt.classList.remove('active'));
          this.classList.add('active');
          const theme = this.dataset.theme;
          applyTheme(theme);
          saveSettings();
        });
      });

      // 窗口大小设置
      const windowInputs = document.querySelectorAll('.size-input');
      windowInputs.forEach(input => {
        input.addEventListener('change', function () {
          const width = document.getElementById('windowWidth').value;
          const height = document.getElementById('windowHeight').value;
          document.querySelector('.game-container').style.maxWidth = width + 'px';
          document.querySelector('.game-container').style.minHeight = height + 'px';
          saveSettings();
        });
      });

      // 保存设置
      function saveSettings() {
        const settings = {
          font: document.querySelector('.font-option.active').dataset.font,
          fontSize: document.getElementById('fontSizeSlider').value,
          theme: document.querySelector('.color-option.active').dataset.theme,
          windowWidth: document.getElementById('windowWidth').value,
          windowHeight: document.getElementById('windowHeight').value
        };
        localStorage.setItem('restaurantGameSettings', JSON.stringify(settings));
        showSaveStatus();
      }

      // 加载设置
      function loadSettings() {
        try {
          const savedSettings = localStorage.getItem('restaurantGameSettings');
          if (savedSettings) {
            const settings = JSON.parse(savedSettings);

            // 应用字体
            if (settings.font) {
              const fontOption = document.querySelector(`[data-font="${settings.font}"]`);
              if (fontOption) {
                document.querySelectorAll('.font-option').forEach(opt => opt.classList.remove('active'));
                fontOption.classList.add('active');
                const root = document.documentElement;
                root.style.setProperty('--font-family', settings.font === 'WenQuanYi' ? '"WenQuanYi Bitmap Song 13px"' : '"Kingnam Maiyuan"');
              }
            }

            // 应用字体大小
            if (settings.fontSize) {
              const fontSizeSlider = document.getElementById('fontSizeSlider');
              const fontSizeValue = document.querySelector('.font-size-value');
              if (fontSizeSlider && fontSizeValue) {
                fontSizeSlider.value = settings.fontSize;
                fontSizeValue.textContent = settings.fontSize + 'px';
                document.documentElement.style.setProperty('--font-size', settings.fontSize + 'px');
              }
            }

            // 应用主题
            if (settings.theme) {
              const themeOption = document.querySelector(`[data-theme="${settings.theme}"]`);
              if (themeOption) {
                document.querySelectorAll('.color-option').forEach(opt => opt.classList.remove('active'));
                themeOption.classList.add('active');
                applyTheme(settings.theme);
              }
            }

            // 应用窗口大小
            if (settings.windowWidth && settings.windowHeight) {
              const container = document.querySelector('.game-container');
              const widthInput = document.getElementById('windowWidth');
              const heightInput = document.getElementById('windowHeight');

              if (container) {
                container.style.maxWidth = settings.windowWidth + 'px';
                container.style.minHeight = settings.windowHeight + 'px';
              }

              if (widthInput) widthInput.value = settings.windowWidth;
              if (heightInput) heightInput.value = settings.windowHeight;
            }
          }
        } catch (error) {
          console.error('加载设置时出错：', error);
        }
      }

      // 显示保存状态
      function showSaveStatus() {
        const saveStatus = document.querySelector('.save-status');
        saveStatus.classList.add('show');
        setTimeout(() => {
          saveStatus.classList.remove('show');
        }, 2000);
      }

      // 应用主题
      function applyTheme(theme) {
        const root = document.documentElement;
        const themes = {
          default: {
            primary: '#453B34',
            border: '#453B34',
            background: '#e8dfd1',
            text: '#453B34'
          },
          dark: {
            primary: '#2C3E50',
            border: '#2C3E50',
            background: '#2d2d2d',
            text: '#f5efe6'
          },
          purple: {
            primary: '#8E44AD',
            border: '#8E44AD',
            background: '#F5EEF8',
            text: '#8E44AD'
          },
          green: {
            primary: '#16A085',
            border: '#16A085',
            background: '#E8F6F3',
            text: '#16A085'
          }
        };

        const selectedTheme = themes[theme];
        if (selectedTheme) {
          root.style.setProperty('--primary-color', selectedTheme.primary);
          root.style.setProperty('--border-color', selectedTheme.border);
          root.style.setProperty('--background-color', selectedTheme.background);
          root.style.setProperty('--text-color', selectedTheme.text);
        }
      }
    });

    // 1. 基础模板定义
    let gameText = `<gametext>$1</gametext>`;

    // 2. 数据提取器
    const DataExtractor = {
      extractMainContent(text) {
        try {
          // 首先匹配 <maintext> 标签内的内容
          const mainTextMatch = text.match(/<maintext>([\s\S]*?)<\/maintext>/);
          if (!mainTextMatch) return null;

          const mainText = mainTextMatch[1].trim();

          // 提取时间 - 匹配"当前时间|"后面的内容
          const timeMatch = mainText.match(/当前时间\|(.*?)(?:\n|$)/);
          const time = timeMatch ? timeMatch[1].trim() : '暂无时间信息';

          // 提取位置 - 匹配"当前位置|"后面的内容
          const locationMatch = mainText.match(/当前位置\|(.*?)(?:\n|$)/);
          const location = locationMatch ? locationMatch[1].trim() : '暂无位置信息';

          // 提取正文 - 匹配"正文|"后面的所有内容直到结束
          const contentMatch = mainText.match(/正文\|([\s\S]*?)(?=选择：|$)/);
          const content = contentMatch ? contentMatch[1].trim() : '暂无内容';

          return {
            '当前时间': time,
            '当前地点': location,
            '正文': content
          };
        } catch (e) {
          console.error('解析主体内容失败:', e);
          return null;
        }
      },

      extractOverviewContent(text) {
        try {
          const match = text.match(/<overview>([\s\S]*?)<\/overview>/);
          if (!match) return null;

          const content = {
            basicInfo: {},
            rareItems: []
          };

          const lines = match[1].trim().split('\n');

          lines.forEach(line => {
            const [key, value] = line.split('|').map(s => s.trim());
            if (!key || !value) return;

            if (key === '稀有道具') {
              // 处理稀有道具，格式：名称,图标,描述
              const [name, icon, effect] = value.split(',').map(s => s.trim());
              content.rareItems.push({ name, icon, effect });
            } else {
              content.basicInfo[key] = value;
            }
          });

          return content;
        } catch (e) {
          console.error('解析营业总览内容失败:', e);
          return null;
        }
      },

      extractDiningContent(text) {
        try {
          const match = text.match(/<review>([\s\S]*?)<\/review>/);
          if (!match) return null;

          const content = {
            reviews: []
          };

          // 将评价文本按顾客分组
          const reviewText = match[1].trim();
          const lines = reviewText.split('\n');

          let currentReview = {};

          lines.forEach(line => {
            const [key, value] = line.split('|').map(s => s.trim());
            if (!key || !value) return;

            // 当遇到新的顾客姓名时，保存前一个评价并开始新的评价
            if (key === '顾客姓名') {
              if (Object.keys(currentReview).length > 0) {
                content.reviews.push(currentReview);
              }
              currentReview = {};
            }

            // 处理不同类型的值
            if (key === '偏好口味' || key === '不喜欢') {
              currentReview[key] = value.split(',').map(t => t.trim());
            } else if (key === '评分') {
              currentReview[key] = parseFloat(value);
            } else {
              currentReview[key] = value;
            }
          });

          // 添加最后一个评价
          if (Object.keys(currentReview).length > 0) {
            content.reviews.push(currentReview);
          }

          return content;
        } catch (e) {
          console.error('解析食堂区域内容失败:', e);
          return null;
        }
      },

      extractKitchenContent(text) {
        try {
          const match = text.match(/<kitchen>([\s\S]*?)<\/kitchen>/);
          if (!match) {
            return {
              ingredients: [],
              equipment: {
                level: 'D',
                description: '基础厨房设备'
              }
            };
          }

          const content = {
            ingredients: [],
            equipment: {}
          };

          const kitchenText = match[1].trim();
          const lines = kitchenText.split('\n');

          lines.forEach(line => {
            const [key, value] = line.split('|').map(s => s.trim());
            if (!key || !value) return;

            if (key === '食材') {
              content.ingredients.push({
                name: value
              });
            } else if (key === '设备等级') {
              content.equipment.level = value;
            } else if (key === '设备描述') {
              content.equipment.description = value;
            }
          });

          return content;
        } catch (e) {
          console.error('解析厨房内容失败:', e);
          return {
            ingredients: [],
            equipment: {
              level: 'D',
              description: '基础厨房设备'
            }
          };
        }
      },

      extractStaffContent(text) {
        try {
          const match = text.match(/<staff>([\s\S]*?)<\/staff>/);
          if (!match) return null;

          const content = {
            staffList: []
          };

          const staffText = match[1].trim();
          const lines = staffText.split('\n').map(line => line.trim()).filter(line => line);
          let currentStaff = {};

          lines.forEach(line => {
            const separatorIndex = line.indexOf('|');
            if (separatorIndex === -1) return;

            const key = line.substring(0, separatorIndex).trim();
            const value = line.substring(separatorIndex + 1).trim();

            // 当遇到新的"员工类型"时，保存前一个员工的信息并开始新的员工
            if (key === '员工类型' && Object.keys(currentStaff).length > 0) {
              content.staffList.push({ ...currentStaff });
              currentStaff = {};
            }

            if (key === '好感度') {
              const match = value.match(/(\d+)（(.+)）/);
              if (match) {
                currentStaff[key] = {
                  value: parseInt(match[1]),
                  description: match[2]
                };
              } else {
                currentStaff[key] = {
                  value: parseInt(value) || 0,
                  description: ''
                };
              }
            } else {
              currentStaff[key] = value;
            }
          });

          // 添加最后一个员工的信息
          if (Object.keys(currentStaff).length > 0) {
            content.staffList.push({ ...currentStaff });
          }

          return content;
        } catch (e) {
          console.error('解析员工信息失败:', e);
          return null;
        }
      },

      extractTaskContent(text) {
        try {
          const match = text.match(/<tasks>([\s\S]*?)<\/tasks>/);
          if (!match) return null;

          const content = {
            mainTask: {
              completed: []
            },
            sideTasks: []
          };

          const taskText = match[1].trim();
          const lines = taskText.split('\n');

          let currentSection = '';

          lines.forEach(line => {
            const [key, value] = line.split('|').map(s => s.trim());
            if (!key || !value) return;

            if (key === '主线任务名称') {
              currentSection = 'main';
              content.mainTask.name = value;
            } else if (key === '主线任务状态') {
              content.mainTask.status = value;
            } else if (key === '主线任务进度') {
              content.mainTask.current = value;
            } else if (key === '已完成项目') {
              content.mainTask.completed.push(value);
            } else if (key === '支线任务') {
              currentSection = 'side';
              const [name, current, status] = value.split(',').map(s => s.trim());
              content.sideTasks.push({
                name,
                current,
                status
              });
            }
          });

          return content;
        } catch (e) {
          console.error('解析任务内容失败:', e);
          return null;
        }
      },

      extractMenuContent(text) {
        try {
          const match = text.match(/<menu>([\s\S]*?)<\/menu>/);
          if (!match) return null;

          const content = {
            dishes: []
          };

          const menuText = match[1].trim();
          const lines = menuText.split('\n');

          let currentDish = null;

          lines.forEach(line => {
            const [key, value] = line.split('|').map(s => s.trim());
            if (!key || !value) return;

            if (key === '菜品名称') {
              if (currentDish) {
                content.dishes.push(currentDish);
              }
              currentDish = {
                name: value
              };
            } else if (currentDish) {
              if (key === '等级') {
                currentDish.level = value;
              } else if (key === '食材要求') {
                currentDish.ingredients = value.split(',').map(s => s.trim());
              } else if (key === '料理要求') {
                currentDish.requirements = value.split(',').map(s => s.trim());
              } else if (key === '描述') {
                currentDish.description = value;
              }
            }
          });

          // 添加最后一个菜品
          if (currentDish) {
            content.dishes.push(currentDish);
          }

          return content;
        } catch (e) {
          console.error('解析菜单内容失败:', e);
          return null;
        }
      }
    };

    // 3. 界面更新器
    const UIUpdater = {
      updateMainContent(content) {
        try {
          if (!content) return;

          const mainSection = document.querySelector('#main');
          if (!mainSection) return;

          mainSection.innerHTML = `
            <h2 class="section-header">餐厅经营</h2>
            <div class="time-location-info">
              <div class="time-info">
                <i class="fas fa-clock info-icon"></i>
                <div>
                  <div class="info-label">当前时间</div>
                  <div class="info-value">${content['当前时间']}</div>
                </div>
              </div>
              <div class="location-info">
                <i class="fas fa-map-marker-alt info-icon"></i>
                <div>
                  <div class="info-label">当前地点</div>
                  <div class="info-value">${content['当前地点']}</div>
                </div>
              </div>
            </div>
            <div class="story-content">
              <p style="white-space: pre-wrap">${content['正文']}</p>
            </div>
          `;

        } catch (error) {
          console.error('更新正文内容时出错：', error);
        }
      },

      updateOverviewContent(content) {
        try {
          if (!content) return;

          const overviewSection = document.querySelector('#overview');
          if (!overviewSection) return;

          // 生成稀有道具HTML
          const generateRareItems = (items) => {
            return items.map(item => `
              <div class="item-tag">
                <i class="fas ${item.icon}"></i>
                ${item.name}（${item.effect}）
              </div>
            `).join('');
          };

          overviewSection.innerHTML = `
            <h2 class="section-header">营业总览</h2>
            <div class="overview-grid">
              <div class="overview-card">
                <h3><i class="fas fa-coins"></i> 当前资金</h3>
                <div class="overview-value">${content.basicInfo['当前资金'] || '¥ 0'}</div>
              </div>

              <div class="overview-card">
                <h3><i class="fas fa-chart-line"></i> 当前月收入</h3>
                <div class="overview-value">${content.basicInfo['月收入'] || '¥ 0/月'}</div>
              </div>

              <div class="overview-card">
                <h3><i class="fas fa-calendar-alt"></i> 来到该世界</h3>
                <div class="overview-value">${content.basicInfo['经营天数'] || '0'} 天</div>
              </div>

              <div class="overview-card">
                <h3><i class="fas fa-star"></i> 餐厅评级</h3>
                <div class="overview-value">${content.basicInfo['餐厅评级'] || '暂无评级'}</div>
              </div>

              <div class="overview-card">
                <h3><i class="fas fa-users"></i> 今日客流量</h3>
                <div class="overview-value">${content.basicInfo['今日客流'] || '0'} 人次</div>
              </div>

              <div class="overview-card">
                <h3><i class="fas fa-gem"></i> 稀有道具</h3>
                <div class="items-list">
                  ${generateRareItems(content.rareItems)}
                </div>
              </div>
            </div>
          `;

        } catch (error) {
          console.error('更新营业总览内容时出错：', error);
        }
      },

      updateDiningContent(content) {
        try {
          if (!content) return;

          const diningSection = document.querySelector('#dining');
          if (!diningSection) return;

          // 生成星级评分HTML
          const generateStars = (rating) => {
            let starsHtml = '';
            for (let i = 1; i <= 5; i++) {
              starsHtml += `<i class="fas ${i <= rating ? 'fa-star' : 'far fa-star'}"></i>`;
            }
            return starsHtml;
          };

          // 生成标签HTML
          const generateTags = (tags) => {
            return tags.map(tag => `<span class="taste-tag">${tag}</span>`).join('');
          };

          // 生成评价卡片HTML
          const generateReviewCards = (reviews) => {
            return reviews.map(review => `
              <div class="review-card">
                <div class="customer-header">
                  <div class="customer-name">${review['顾客姓名'] || '匿名顾客'}</div>
                  <div class="visit-count"><i class="fas fa-history"></i> 第${review['光临次数'] || '1'}次光临</div>
                </div>
                <div class="taste-preferences">
                  <div class="taste-group">
                    <h4>偏好口味</h4>
                    <div class="taste-tags">
                      ${generateTags(review['偏好口味'] || [])}
                    </div>
                  </div>
                  <div class="taste-group">
                    <h4>不喜欢</h4>
                    <div class="taste-tags">
                      ${generateTags(review['不喜欢'] || [])}
                    </div>
                  </div>
                </div>
                <div class="rating">
                  <div class="stars">
                    ${generateStars(review['评分'] || 0)}
                  </div>
                  <span>${review['评分'] || '0.0'}分</span>
                </div>
                <div class="review-text">
                  "${review['评价内容'] || ''}"
                </div>
              </div>
            `).join('');
          };

          diningSection.innerHTML = `
            <h2 class="section-header">食堂区域</h2>
            <div class="customer-reviews">
              ${generateReviewCards(content.reviews)}
            </div>
          `;

        } catch (error) {
          console.error('更新食堂区域内容时出错：', error);
        }
      },

      updateKitchenContent(content) {
        try {
          if (!content) {
            content = { ingredients: [] };
          }

          const kitchenSection = document.querySelector('#kitchen');
          if (!kitchenSection) return;

          // 生成食材表格行HTML
          const generateIngredientRows = (ingredients) => {
            return ingredients.map(ingredient => {
              const name = ingredient.name;
              return `
                <tr>
                  <td>
                    <div class="ingredient-item" draggable="true" data-name="${name}">
                      ${name}
                    </div>
                  </td>
                </tr>
              `;
            }).join('');
          };

          kitchenSection.innerHTML = `
            <h2 class="section-header">厨房管理</h2>
            <div class="kitchen-grid">
              <div class="kitchen-card">
                <h3><i class="fas fa-carrot"></i> 食材库存</h3>
                <table class="ingredients-table">
                  ${generateIngredientRows(content.ingredients)}
                </table>
              </div>



              <div class="kitchen-card">
                <h3><i class="fas fa-magic"></i> 创造新菜品</h3>
                <p>将食材拖拽到下方区域来创造新的菜品</p>
                <div class="new-dish-area">
                  <div class="selected-ingredients"></div>
                </div>
                <button class="create-dish-button" disabled>
                  <i class="fas fa-utensils"></i>
                  开始创造新菜品
                </button>
              </div>
            </div>

            <div class="kitchen-card">
                <h3><i class="fas fa-tools"></i> 设备信息</h3>
                <div class="equipment-level">${content.equipment?.level || 'D'}</div>
                <p class="equipment-desc">
                  ${content.equipment?.description || '基础厨房设备'}
                </p>
              </div>
          `;

          // 添加拖拽相关的事件监听
          const ingredientItems = kitchenSection.querySelectorAll('.ingredient-item');
          const newDishArea = kitchenSection.querySelector('.new-dish-area');
          const selectedIngredientsArea = kitchenSection.querySelector('.selected-ingredients');
          const createButton = kitchenSection.querySelector('.create-dish-button');

          // 更新创建按钮状态的函数
          const updateCreateButtonState = () => {
            const hasIngredients = selectedIngredientsArea.children.length > 0;
            createButton.disabled = !hasIngredients;
          };

          // 创建菜品的函数
          const createNewDish = () => {
            const selectedIngredients = Array.from(selectedIngredientsArea.children)
              .map(el => el.dataset.name);

            const ingredientsList = selectedIngredients.join('，');
            const outputMessage = `{{user}}决定使用${ingredientsList}，制作一道新的料理。`;

            const commands = [];
            commands.push(`/send ${outputMessage}`);
            triggerSlash(commands.join('|'));

            // 清空已选食材
            selectedIngredientsArea.innerHTML = '';
            updateCreateButtonState();
          };

          // 为创建按钮添加点击事件
          createButton.addEventListener('click', createNewDish);

          ingredientItems.forEach(item => {
            item.addEventListener('dragstart', (e) => {
              item.classList.add('dragging');
              e.dataTransfer.setData('text/plain', JSON.stringify({
                name: item.dataset.name
              }));
            });

            item.addEventListener('dragend', () => {
              item.classList.remove('dragging');
            });
          });

          newDishArea.addEventListener('dragover', (e) => {
            e.preventDefault();
            newDishArea.classList.add('drag-over');
          });

          newDishArea.addEventListener('dragleave', () => {
            newDishArea.classList.remove('drag-over');
          });

          newDishArea.addEventListener('drop', (e) => {
            e.preventDefault();
            newDishArea.classList.remove('drag-over');

            const data = JSON.parse(e.dataTransfer.getData('text/plain'));
            const existingIngredient = selectedIngredientsArea.querySelector(`[data-name="${data.name}"]`);

            if (!existingIngredient) {
              const ingredientElement = document.createElement('div');
              ingredientElement.className = 'selected-ingredient';
              ingredientElement.dataset.name = data.name;
              ingredientElement.innerHTML = `
                ${data.name}
                <span class="remove-ingredient">×</span>
              `;

              ingredientElement.querySelector('.remove-ingredient').addEventListener('click', () => {
                ingredientElement.remove();
                updateCreateButtonState();
              });

              selectedIngredientsArea.appendChild(ingredientElement);
              updateCreateButtonState();
            }
          });

        } catch (error) {
          console.error('更新厨房内容时出错：', error);
          // 发生错误时显示错误信息
          const kitchenSection = document.querySelector('#kitchen');
          if (kitchenSection) {
            kitchenSection.innerHTML = `
              <h2 class="section-header">厨房管理</h2>
              <div class="kitchen-grid">
                <div class="kitchen-card">
                  <h3><i class="fas fa-exclamation-triangle"></i> 加载错误</h3>
                  <p>抱歉，加载厨房内容时出现错误。</p>
                </div>
              </div>
            `;
          }
        }
      },

      updateStaffContent(content) {
        try {
          if (!content || !content.staffList || content.staffList.length === 0) {
            console.log('No staff content to display');
            return;
          }

          const staffSection = document.querySelector('#staff');
          if (!staffSection) return;

          // 生成好感度条HTML
          const generateFavorBar = (favor) => {
            if (!favor) return '';
            return `
              <div class="staff-favor">
                <div class="favor-bar">
                  <div class="favor-value" style="width: ${favor.value}%"></div>
                </div>
                <div class="favor-text">${favor.value}（${favor.description}）</div>
              </div>
            `;
          };

          // 生成员工卡片HTML
          const generateStaffCards = (staffList) => {
            return staffList.map(staff => `
              <div class="staff-card">
                <div class="staff-header">
                  <div class="staff-type">${staff['员工类型'] || '未知职位'}</div>
                  <div class="staff-name">${staff['姓名'] || '未知姓名'}</div>
                  <div class="staff-level">${staff['等级'] || 'N/A'}</div>
                </div>
                <div class="staff-content">
                  <div class="staff-info-item">
                    <div class="staff-info-label">好感度</div>
                    ${generateFavorBar(staff['好感度'])}
                  </div>
                  <div class="staff-info-item">
                    <div class="staff-info-label">经历</div>
                    <div class="staff-info-value">${staff['经历'] || '暂无经历'}</div>
                  </div>
                  <div class="staff-info-item">
                    <div class="staff-info-label">当前想法</div>
                    <div class="staff-info-value">${staff['当前想法'] || '暂无想法'}</div>
                  </div>
                  <div class="staff-info-item">
                    <div class="staff-info-label">年龄</div>
                    <div class="staff-info-value">${staff['年龄'] || '未知'}</div>
                  </div>
                  <div class="staff-info-item">
                    <div class="staff-info-label">性格特征</div>
                    <div class="staff-info-value">${staff['性格特征'] || '暂无描述'}</div>
                  </div>
                  <div class="staff-info-item">
                    <div class="staff-info-label">外貌</div>
                    <div class="staff-description">${staff['外貌'] || '暂无描述'}</div>
                  </div>
                  <div class="staff-info-item">
                    <div class="staff-info-label">穿着</div>
                    <div class="staff-description">${staff['穿着'] || '暂无描述'}</div>
                  </div>
                </div>
              </div>
            `).join('');
          };

          staffSection.innerHTML = `
            <h2 class="section-header">员工信息</h2>
            <div class="staff-container">
              ${generateStaffCards(content.staffList)}
            </div>
          `;

        } catch (error) {
          console.error('更新员工信息时出错：', error);
          console.error(error.stack);
        }
      },

      updateTaskContent(content) {
        try {
          if (!content) return;

          const taskSection = document.querySelector('#tasks');
          if (!taskSection) return;

          // 生成已完成项目的HTML
          const generateCompletedItems = (items) => {
            return items.map(item => `
              <div class="completed-tag">
                <i class="fas fa-check-circle"></i>
                ${item}
              </div>
            `).join('');
          };

          // 生成支线任务的HTML
          const generateSideTasks = (tasks) => {
            return tasks.map(task => {
              // 只有当任务名称存在时才显示任务
              if (!task.name) return '';

              return `
                <div class="side-task">
                  <div class="side-task-info">
                    <div class="side-task-name">${task.name}</div>
                    ${task.current ? `<div class="side-task-current">${task.current}</div>` : ''}
                  </div>
                  ${task.status ? `<span class="task-status">${task.status}</span>` : ''}
                </div>
              `;
            }).join('');
          };

          taskSection.innerHTML = `
            <h2 class="section-header">任务中心</h2>
            <div class="tasks-container">
              <!-- 主线任务 -->
              <div class="task-section">
                <div class="task-header">
                  <i class="fas fa-star"></i>
                  主线任务
                </div>
                <div class="task-content">
                  <div class="task-item">
                    <div class="task-name">
                      <span>${content.mainTask.name || ''}</span>
                      ${content.mainTask.status ? `<span class="task-status">${content.mainTask.status}</span>` : ''}
                    </div>
                    ${content.mainTask.current ? `<div class="task-current">${content.mainTask.current}</div>` : ''}
                    <div class="completed-items">
                      ${generateCompletedItems(content.mainTask.completed)}
                    </div>
                  </div>
                </div>
              </div>

              <!-- 支线任务 -->
              <div class="task-section">
                <div class="task-header">
                  <i class="fas fa-tasks"></i>
                  支线任务
                </div>
                <div class="task-content">
                  ${content.sideTasks && content.sideTasks.length > 0 ? generateSideTasks(content.sideTasks) : '<div class="side-task">暂无支线任务</div>'}
                </div>
              </div>
            </div>
          `;

        } catch (error) {
          console.error('更新任务内容时出错：', error);
        }
      },

      updateMenuContent(content) {
        try {
          if (!content) return;

          const menuSection = document.querySelector('#menu');
          if (!menuSection) return;

          // 生成要求标签HTML
          const generateRequirementTags = (tags) => {
            return tags.map(tag => `
              <span class="requirement-tag">${tag}</span>
            `).join('');
          };

          // 生成菜品卡片HTML
          const generateDishCards = (dishes) => {
            return dishes.map(dish => `
              <div class="dish-card">
                <div class="dish-header">
                  <div class="dish-name">${dish.name}</div>
                  <div class="dish-level">${dish.level}</div>
                </div>
                <div class="dish-content">
                  <div class="dish-requirements">
                    <div class="requirement-group">
                      <div class="requirement-label">食材要求</div>
                      <div class="requirement-tags">
                        ${generateRequirementTags(dish.ingredients || [])}
                      </div>
                    </div>
                    <div class="requirement-group">
                      <div class="requirement-label">料理要求</div>
                      <div class="requirement-tags">
                        ${generateRequirementTags(dish.requirements || [])}
                      </div>
                    </div>
                  </div>
                  <div class="dish-description">
                    ${dish.description || '暂无描述'}
                  </div>
                </div>
              </div>
            `).join('');
          };

          menuSection.innerHTML = `
            <h2 class="section-header">菜单管理</h2>
            <div class="menu-container">
              <div class="menu-category">
                <div class="menu-header">
                  <i class="fas fa-utensils"></i>
                  当前招牌
                </div>
                <div class="dish-grid">
                  ${generateDishCards(content.dishes)}
                </div>
              </div>
            </div>
          `;

        } catch (error) {
          console.error('更新菜单内容时出错：', error);
        }
      }
    };

    // 4. 主要的数据处理流程
    function processGameText(text) {
      try {
        // 处理主要内容
        const mainContent = DataExtractor.extractMainContent(text);
        if (mainContent) {
          UIUpdater.updateMainContent(mainContent);
        }

        // 处理营业总览内容
        const overviewContent = DataExtractor.extractOverviewContent(text);
        if (overviewContent) {
          UIUpdater.updateOverviewContent(overviewContent);
        }

        // 处理食堂区域内容
        const diningContent = DataExtractor.extractDiningContent(text);
        if (diningContent) {
          UIUpdater.updateDiningContent(diningContent);
        }

        // 处理厨房内容
        const kitchenContent = DataExtractor.extractKitchenContent(text);
        if (kitchenContent) {
          UIUpdater.updateKitchenContent(kitchenContent);
        }

        // 处理员工信息
        const staffContent = DataExtractor.extractStaffContent(text);
        if (staffContent) {
          UIUpdater.updateStaffContent(staffContent);
        }

        // 处理任务内容
        const taskContent = DataExtractor.extractTaskContent(text);
        if (taskContent) {
          UIUpdater.updateTaskContent(taskContent);
        }

        // 处理菜单内容
        const menuContent = DataExtractor.extractMenuContent(text);
        if (menuContent) {
          UIUpdater.updateMenuContent(menuContent);
        }

        console.log('数据处理完成:', { mainContent, overviewContent, diningContent, kitchenContent, staffContent, taskContent, menuContent });
      } catch (error) {
        console.error('处理游戏数据时出错：', error);
      }
    }

    // 5. 页面加载完成后初始化
    document.addEventListener('DOMContentLoaded', function () {
      if (typeof gameText !== 'undefined') {
        processGameText(gameText);
      }
    });
  </script>
</body>

</html>
