  <script>
    document.getElementById('worldForm').addEventListener('submit', function (e) {
      e.preventDefault();

      // 获取表单数据
      const worldName = document.querySelector('input[type="text"]').value;
      const worldDescription = document.querySelector('textarea[name="worldDescription"]').value;
      const era = document.querySelector('input[name="era"]:checked').value;
      const system = document.querySelector('input[name="system"]:checked').value;
      const birthplace = document.querySelector('input[name="birthplace"]').value;
      const initialFunds = document.querySelector('input[name="initialFunds"]').value;
      const initialIngredients = document.querySelector('textarea[name="initialIngredients"]').value;

      // 准备命令列表
      const commands = [];

      // 设置世界名称和描述
      commands.push(`/setvar key=world ${worldName}`);
      if (worldDescription) {
        commands.push(`/setvar key=worldDescription ${worldDescription}`);
      }

      // 设置出生地
      commands.push(`/setvar key=birthplace ${birthplace}`);

      // 设置初始资金
      commands.push(`/setvar key=initialFunds ${initialFunds}`);

      // 设置初始食材
      if (initialIngredients) {
        commands.push(`/setvar key=initialIngredients ${initialIngredients}`);
      }

      // 设置时代
      commands.push(`/setvar key=era ${era}`);

      // 设置修炼体系
      commands.push(`/setvar key=system ${system}`);

      // 准备输出消息
      let outputMessage = `{{user}}选择了${worldName}世界`;

      // 添加世界描述
      if (worldDescription) {
        outputMessage += `\n\n世界描述：${worldDescription}`;
      }

      // 添加出生地信息
      outputMessage += `\n\n出生地：${birthplace}`;

      // 添加初始资金信息
      outputMessage += `\n初始资金：${initialFunds}金币`;

      // 添加初始食材信息
      if (initialIngredients) {
        outputMessage += `\n初始食材：${initialIngredients}`;
      }

      // 添加时代信息
      outputMessage += `\n\n所处时代：${era}`;

      // 添加修炼体系信息
      outputMessage += `\n修炼体系：${system}`;

      // 设置entry相关命令
      const entryContent = {
        world: worldName,
        description: worldDescription,
        birthplace: birthplace,
        initialFunds: initialFunds,
        initialIngredients: initialIngredients,
        era: era,
        system: system
      };

      commands.push(`/setentryfield file=1ysj uid=0 field=content ${JSON.stringify(entryContent)}`);
      commands.push(`/setentryfield file=1ysj uid=0 field=constant 1`);
      commands.push(`/setentryfield file=1ysj uid=0 field=position 4`);
      commands.push(`/setentryfield file=1ysj uid=0 field=role 0`);

      // 发送消息和触发器
      commands.push(`/send ${outputMessage}`);
      commands.push('/trigger');

      // 执行所有命令
      if (typeof triggerSlash === 'function') {
        triggerSlash(commands.join('|'));
      } else {
        console.log('Commands to execute:', commands.join('|'));
      }

      // 添加转场效果
      document.body.style.opacity = 0;
      setTimeout(() => {
        window.location.href = 'restaurant_game.html';
      }, 1000);
    });
  </script>
</body>

</html>
