      box-shadow: 0 4px 20px rgba(69, 59, 52, 0.15);
      background-image:
        linear-gradient(rgba(255, 255, 255, 0.1) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255, 255, 255, 0.1) 1px, transparent 1px);
      background-size: 20px 20px;
    }

    .header-section {
      text-align: center;
      margin-bottom: 40px;
    }

    .main-title {
      font-size: 2em;
