      margin-bottom: 10px;
      position: relative;
      display: inline-block;
      text-shadow: 1px 1px 2px rgba(69, 59, 52, 0.2);
    }

    .main-title:before,
    .main-title:after {
      content: '✦';
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      color: var(--primary-color);
      font-size: 0.8em;
    }

    .main-title:before {
      left: -30px;
