<body>
  <div class="start-container">
    <div class="header-section">
      <h1 class="main-title">开始新的异世界酒馆旅程</h1>
    </div>

    <form id="worldForm">
      <div class="form-group">
        <label class="form-label">
          <i class="fas fa-globe icon-prefix"></i>
          请输入你想开始游戏的异世界名称
        </label>
        <input type="text" class="form-input" required placeholder="例如：赛博城邦">
      </div>

